      "ja": "デガは、孤児となった従妹のリュシーと、彼女を引き取った叔父アンリを描きました。おそらく1875年、ナポリ滞在中の制作です。喪服の黒と、互いに似た頭の傾きが二人を結びつける一方、背景の扉の端と椅子の背が画面を分けています。薄く塗られた部分や描き残しから、未完の作品と考えられます。簡素な背景は、二人の頭部と上半身を際立たせています。"
